export function fixtureMap(columns=32,rows=4,stage:'I'|'II'|'III'='I'):BattleMap {
  const cells:BattleMap['cells']=[];for(let r=-Math.floor(rows/2);r<Math.ceil(rows/2);r++)for(let u=-Math.floor(columns/2);u<Math.ceil(columns/2);u++){const q=u-Math.floor(r/2),id=`c:${q}:${r}`;cells.push({id,q,r,terrain:'ground',groundHeight:0,buildingId:null,roofHeight:null,surfaces:[{id:`${id}:ground`,cellId:id,kind:'ground',z:0,walkable:true}],occluder:null});}
  const n=stage==='I'?9:stage==='II'?14:24;return {schemaVersion:2,id:'fixture',version:'M1.2-fixture',geometryVersion:'G1',stage,dimensions:{columns,rows,offset:'odd-r',orientation:'pointy-top'},renderScale:{hexRadius:10,heightStep:7,humanHeight:4.2,shear:0,verticalProjection:1,absoluteMetersPerCell:null},cells,buildings:[],structures:[],spawnSlots:(['A','B'] as const).flatMap(team=>Array.from({length:n},(_,i)=>({team,index:i,surfaceId:cells[team==='A'?i:cells.length-1-i]!.surfaces[0]!.id})))};
}
export function calibrationFixture(kind:'residential'|'mall'): {map:BattleMap;origin: {x:string;y:string;z:string};aim:{x:string;y:string;z:string};originSurface:string;aimCell:string;initialVolume:number} {
  const map=fixtureMap(16,16),residential=kind==='residential',height=residential?2:3,min=residential?0:-3,max=residential?1:2,buildingId=kind;const ids:string[]=[];
  for(const cell of map.cells){const u=cell.q+Math.floor(cell.r/2);if(u<min||u>max||cell.r<min||cell.r>max)continue;ids.push(cell.id);cell.buildingId=buildingId;cell.roofHeight=height;cell.terrain='building';cell.surfaces=[{id:`${cell.id}:roof`,cellId:cell.id,kind:'roof',z:height,walkable:true}];for(let layerIndex=0;layerIndex<height;layerIndex++){const id=`${buildingId}/${cell.id}/${layerIndex}`;map.structures!.push({id,buildingId,cellId:cell.id,layerIndex,materialId:residential?'residential':'reinforced',maxDurability:residential?300:1200,currentDurability:residential?300:1200,supportIds:layerIndex?[`${buildingId}/${cell.id}/${layerIndex-1}`]:[]});}}
  map.buildings=[{id:buildingId,name:kind,cellIds:ids,roofKind:'flat',category:kind,materialId:residential?'residential':'reinforced'}];const r=residential?0:-1,oq=(residential?-1:-4)-Math.floor(r/2),aq=(residential?0:-1)-Math.floor(r/2);return {map,origin:{x:String(1732051*(2*oq+r)),y:String(3000000*r),z:'560000'},aim:{x:String(1732051*(2*aq+r)),y:String(3000000*r),z:'700000'},originSurface:`c:${oq}:${r}:ground`,aimCell:`c:${aq}:${r}`,initialVolume:ids.length*height};
}
